'use client';

import * as React from 'react';

// @interlace/daily-puzzle v1.0.0 — Interlace design system.
// Docs, props and live preview: https://ds.interlace.tools/c/daily-puzzle
// What changed since: https://ds.interlace.tools/c/daily-puzzle#history
// Generated banner — keep it, the upgrade diff reads this version.

/**
 * @interlace/ui — DailyPuzzle
 *
 * The frame around a daily game: its name, today's number and date, how far
 * through the rounds the player is, and, once they finish, a countdown to the
 * next one. The game itself is the children, so any round (a CloserGame, a
 * GuessReveal, your own) sits inside the same shell.
 *
 * ## Anatomy
 *
 *   DailyPuzzle                    (section — data-slot="daily-puzzle", data-state=playing|done, labelled by the title)
 *     ├─ header                    (data-slot="daily-puzzle-header")
 *     │   ├─ h2                    (data-slot="daily-puzzle-title")
 *     │   ├─ p                     (data-slot="daily-puzzle-meta": "No. 42 · Tuesday, November 24")
 *     │   └─ div                   (data-slot="daily-puzzle-aside": a compact Streak, a menu)
 *     ├─ div                       (data-slot="daily-puzzle-progress": "Round 2 of 3" + marks)
 *     └─ div                       (data-slot="daily-puzzle-body", keyed by round so each one arrives)
 *
 *   DailyPuzzleCountdown           (p — data-slot="daily-puzzle-countdown": "Next puzzle in 5 h 12 min")
 *
 * ## Rounds
 *
 * `rounds` is how many there are and `round` the one in play (1-based).
 * The progress line is a polite live region, so moving on is announced.
 * When `done`, every mark fills and the line says so. Each new round's body
 * rises in once (150ms, `motion-safe:` only).
 *
 * ## The countdown
 *
 * The server cannot know the player's clock, so the server HTML says "Next
 * puzzle at midnight" (`labels.nextAtMidnight`) and the browser replaces it
 * with the time left, read in `timeZone`, ticking each minute (each second
 * in the last minute). At zero it calls `onNextDay`, so the page can load
 * the new puzzle.
 *
 * ## MIN_VIEWPORT — 320
 *
 * | Rule | Concept                   | Where in this file                                     |
 * | ---- | ------------------------- | ------------------------------------------------------ |
 * | R4   | Extends native el         | `React.ComponentProps<'section'>`                      |
 * | R6   | data-slot per part        | daily-puzzle / -header / -title / -meta / -aside / -progress / -body / -countdown |
 * | R7   | cn + ...rest              | `cn(…, className)` + `{...props}`                      |
 * | R14  | Declares min viewport     | `data-min-viewport` + exported const                   |
 * | R19  | Tokens only               | primary, input, muted-foreground, border               |
 * | R26  | A11y                      | labelled section; progress in words, announced; real `<time>` |
 */

import { cn } from '@/lib/utils';
import { dayKey, dayKeyToDate, msUntilNextDay, type DayKey } from '@/components/ui/games/daily';

export const MIN_VIEWPORT = 320 as const;

interface DailyPuzzleLabels {
  /** @default n => `No. ${n}` */
  number?: (n: string) => string;
  /** @default (round, rounds) => `Round ${round} of ${rounds}` */
  progress?: (round: number, rounds: number) => string;
  /** @default 'All done for today' */
  done?: string;
}

type DailyPuzzleProps = Omit<React.ComponentProps<'section'>, 'title'> & {
  /** The game's name. Rendered as an h2; `headingLevel` changes the element only. */
  title: React.ReactNode;
  /** @default 2 */
  headingLevel?: 1 | 2 | 3;
  /** Today's puzzle number (see `puzzleNumber`). */
  number?: number;
  /** Today's day key, shown as a date. */
  day?: DayKey;
  /** Rounds in today's puzzle. Leave out for a one-round game. */
  rounds?: number;
  /** The round in play, 1-based. @default 1 */
  round?: number;
  /** The player has finished today's puzzle. */
  done?: boolean;
  /** Beside the title: a compact Streak, a help button. */
  aside?: React.ReactNode;
  locale?: string;
  labels?: DailyPuzzleLabels;
};

function DailyPuzzle({
  title,
  headingLevel = 2,
  number,
  day,
  rounds,
  round = 1,
  done = false,
  aside,
  locale,
  labels,
  className,
  children,
  ...props
}: DailyPuzzleProps) {
  const titleId = React.useId();
  const Heading = `h${headingLevel}` as const;
  const meta: string[] = [];
  if (number !== undefined) {
    const n = new Intl.NumberFormat(locale).format(number);
    meta.push(labels?.number ? labels.number(n) : `No. ${n}`);
  }
  if (day) {
    meta.push(
      new Intl.DateTimeFormat(locale, { weekday: 'long', month: 'long', day: 'numeric', timeZone: 'UTC' }).format(
        dayKeyToDate(day),
      ),
    );
  }
  const current = Math.min(Math.max(round, 1), rounds ?? 1);
  const progress = done
    ? (labels?.done ?? 'All done for today')
    : (labels?.progress ?? ((r: number, of: number) => `Round ${r} of ${of}`))(current, rounds ?? 1);

  return (
    <section
      data-slot="daily-puzzle"
      data-state={done ? 'done' : 'playing'}
      data-min-viewport={String(MIN_VIEWPORT)}
      aria-labelledby={titleId}
      className={cn('grid gap-5', className)}
      {...props}
    >
      <header data-slot="daily-puzzle-header" className="flex flex-wrap items-start justify-between gap-x-4 gap-y-2">
        <div className="grid min-w-0 gap-1">
          <Heading id={titleId} data-slot="daily-puzzle-title" className="font-heading text-h3 font-semibold text-balance">
            {title}
          </Heading>
          {meta.length ? (
            <p data-slot="daily-puzzle-meta" className="text-muted-foreground text-sm">
              {number !== undefined && day ? (
                <>
                  {meta[0]} <span aria-hidden>·</span> <time dateTime={day}>{meta[1]}</time>
                </>
              ) : day ? (
                <time dateTime={day}>{meta[0]}</time>
              ) : (
                meta[0]
              )}
            </p>
          ) : null}
        </div>
        {aside ? (
          <div data-slot="daily-puzzle-aside" className="flex shrink-0 items-center gap-2">
            {aside}
          </div>
        ) : null}
      </header>

      {rounds && rounds > 1 ? (
        <div data-slot="daily-puzzle-progress" className="flex flex-wrap items-center gap-3">
          <ol aria-hidden className="flex gap-1.5">
            {Array.from({ length: rounds }, (_, i) => {
              const state = done || i + 1 < current ? 'done' : i + 1 === current ? 'current' : 'next';
              return (
                <li
                  key={i}
                  data-state={state}
                  className={cn(
                    'h-1.5 w-6 rounded-full',
                    'motion-safe:transition-colors motion-safe:duration-(--duration-medium) motion-safe:ease-enter',
                    state === 'done' && 'bg-primary',
                    state === 'current' && 'bg-primary/40 ring-primary ring-1',
                    state === 'next' && 'bg-input',
                  )}
                />
              );
            })}
          </ol>
          <p aria-live="polite" className="text-muted-foreground text-sm font-medium">
            {progress}
          </p>
        </div>
      ) : done ? (
        <p data-slot="daily-puzzle-progress" aria-live="polite" className="text-muted-foreground text-sm font-medium">
          {progress}
        </p>
      ) : null}

      <div
        key={done ? 'done' : current}
        data-slot="daily-puzzle-body"
        className="motion-safe:transition-[translate,opacity] motion-safe:duration-(--duration-base) motion-safe:ease-enter motion-safe:starting:translate-y-2 motion-safe:starting:opacity-0"
      >
        {children}
      </div>
    </section>
  );
}
DailyPuzzle.displayName = 'DailyPuzzle';

interface DailyPuzzleCountdownProps extends Omit<React.ComponentProps<'p'>, 'children'> {
  /** IANA zone the next day starts in. @default the runtime's */
  timeZone?: string;
  /** Called once when the next day starts. */
  onNextDay?: () => void;
  locale?: string;
  labels?: {
    /** Server HTML, before the clock is known. @default 'Next puzzle at midnight' */
    nextAtMidnight?: string;
    /** @default time => `Next puzzle in ${time}` */
    nextIn?: (time: string) => string;
    /** @default 'A new puzzle is ready' */
    ready?: string;
  };
}

/** Time left in the locale's own short unit words, such as "5 hr 12 min", "12 min" or "45 sec" in en-US. */
function formatLeft(ms: number, locale?: string) {
  const unit = (u: 'hour' | 'minute' | 'second', n: number) =>
    new Intl.NumberFormat(locale, { style: 'unit', unit: u, unitDisplay: 'short' }).format(n);
  if (ms < 60_000) return unit('second', Math.max(0, Math.ceil(ms / 1000)));
  const minutes = Math.ceil(ms / 60_000);
  const h = Math.floor(minutes / 60);
  const m = minutes % 60;
  return h > 0 ? (m > 0 ? `${unit('hour', h)} ${unit('minute', m)}` : unit('hour', h)) : unit('minute', m);
}

function DailyPuzzleCountdown({ timeZone, onNextDay, locale, labels, className, ...props }: DailyPuzzleCountdownProps) {
  const [left, setLeft] = React.useState<number | null>(null);
  const onNextDayRef = React.useRef(onNextDay);
  onNextDayRef.current = onNextDay;

  React.useEffect(() => {
    let timer: ReturnType<typeof setTimeout>;
    const startDay = dayKey(Date.now(), timeZone);
    const tick = () => {
      const now = Date.now();
      if (dayKey(now, timeZone) !== startDay) {
        setLeft(0);
        onNextDayRef.current?.();
        return;
      }
      const ms = msUntilNextDay(now, timeZone);
      setLeft(ms);
      // Tick as each minute turns; every second in the last minute.
      timer = setTimeout(tick, (ms <= 60_000 ? ms % 1000 : ms % 60_000) + 20);
    };
    tick();
    return () => clearTimeout(timer);
  }, [timeZone]);

  const text =
    left === null
      ? (labels?.nextAtMidnight ?? 'Next puzzle at midnight')
      : left === 0
        ? (labels?.ready ?? 'A new puzzle is ready')
        : (labels?.nextIn ?? ((t: string) => `Next puzzle in ${t}`))(formatLeft(left, locale));

  return (
    <p
      data-slot="daily-puzzle-countdown"
      data-state={left === 0 ? 'ready' : 'waiting'}
      className={cn('text-muted-foreground text-sm tabular-nums', className)}
      {...props}
    >
      {/* The ticks stay quiet; only the day turning is announced. A live region
          must exist before its text changes, so it is always rendered. */}
      <span aria-hidden={left === 0 || undefined}>{text}</span>
      <span data-slot="daily-puzzle-countdown-status" aria-live="polite" className="sr-only">
        {left === 0 ? text : ''}
      </span>
    </p>
  );
}
DailyPuzzleCountdown.displayName = 'DailyPuzzleCountdown';

export { DailyPuzzle, DailyPuzzleCountdown, formatLeft };
export type { DailyPuzzleProps, DailyPuzzleLabels, DailyPuzzleCountdownProps };

export type DayKey = string;

const DAY_MS = 86_400_000;
const KEY_RE = /^(\d{4})-(\d{2})-(\d{2})$/;

/**
 * The calendar day `date` falls on in `timeZone` (an IANA name such as
 * `"Europe/Paris"`). Without a time zone, the runtime's own is used, which on
 * a server is usually UTC: pass the player's zone when the page renders on
 * one.
 */
export function dayKey(date: Date | number = Date.now(), timeZone?: string): DayKey {
  const parts = new Intl.DateTimeFormat('en-US', {
    timeZone,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
  }).formatToParts(typeof date === 'number' ? new Date(date) : date);
  const part = Object.fromEntries(parts.map((p) => [p.type, p.value]));
  return `${part.year}-${part.month}-${part.day}`;
}

/** True when `value` is a well-formed day key for a real date. */
export function isDayKey(value: unknown): value is DayKey {
  if (typeof value !== 'string') return false;
  const m = KEY_RE.exec(value);
  if (!m) return false;
  const d = new Date(Date.UTC(+m[1], +m[2] - 1, +m[3]));
  return d.getUTCFullYear() === +m[1] && d.getUTCMonth() === +m[2] - 1 && d.getUTCDate() === +m[3];
}

function toUtc(key: DayKey): number {
  const m = KEY_RE.exec(key);
  if (!m) throw new RangeError(`Not a day key: "${key}" (expected YYYY-MM-DD)`);
  return Date.UTC(+m[1], +m[2] - 1, +m[3]);
}

/** Midnight UTC of the day, as a Date: the safe way to format a key with Intl. */
export function dayKeyToDate(key: DayKey): Date {
  return new Date(toUtc(key));
}

/** The key `days` after `key` (negative goes back). */
export function addDays(key: DayKey, days: number): DayKey {
  return new Date(toUtc(key) + days * DAY_MS).toISOString().slice(0, 10);
}

/** Whole days from `from` to `to`; negative when `to` is earlier. */
export function daysBetween(from: DayKey, to: DayKey): number {
  return Math.round((toUtc(to) - toUtc(from)) / DAY_MS);
}

/** Day of the week, 0 for Sunday to 6 for Saturday, as `Date.getDay` counts. */
export function weekdayOf(key: DayKey): number {
  return new Date(toUtc(key)).getUTCDay();
}

/**
 * The puzzle's number: 1 on `firstDay`, 2 the day after. Before `firstDay`
 * it is 0 or less, which a caller should treat as "not started".
 */
export function puzzleNumber(key: DayKey, firstDay: DayKey): number {
  return daysBetween(firstDay, key) + 1;
}

/** FNV-1a, 32-bit: a small, stable string hash for seeds. */
export function hashString(value: string): number {
  let h = 0x811c9dc5;
  for (let i = 0; i < value.length; i++) {
    h ^= value.charCodeAt(i);
    h = Math.imul(h, 0x01000193);
  }
  return h >>> 0;
}

/**
 * A seeded generator of numbers in [0, 1) (mulberry32). Good enough to deal
 * puzzles and shuffle answers the same way everywhere; not for anything
 * secret.
 */
export function seededRandom(seed: number | string): () => number {
  let a = typeof seed === 'string' ? hashString(seed) : seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4_294_967_296;
  };
}

/** A copy of `items` in a seeded order (Fisher–Yates). */
export function seededShuffle<T>(items: readonly T[], seed: number | string): T[] {
  const out = items.slice();
  const random = seededRandom(seed);
  for (let i = out.length - 1; i > 0; i--) {
    const j = Math.floor(random() * (i + 1));
    [out[i], out[j]] = [out[j] as T, out[i] as T];
  }
  return out;
}

export interface DailyIndexOptions {
  /** The day puzzle 1 ran. */
  firstDay: DayKey;
  /** `sequence` walks the pool in order; `shuffle` deals it in a seeded order per cycle. @default 'sequence' */
  order?: 'sequence' | 'shuffle';
  /** Changes the shuffled order. @default 'daily' */
  seed?: string;
}

/**
 * Which item of a pool of `size` the day gets, or -1 for an empty pool or a
 * day before `firstDay`.
 */
export function dailyIndex(key: DayKey, size: number, options: DailyIndexOptions): number {
  const n = puzzleNumber(key, options.firstDay);
  if (size <= 0 || n < 1) return -1;
  const position = (n - 1) % size;
  if ((options.order ?? 'sequence') === 'sequence') return position;
  const cycle = Math.floor((n - 1) / size);
  const order = seededShuffle(
    Array.from({ length: size }, (_, i) => i),
    `${options.seed ?? 'daily'}:${cycle}`,
  );
  return order[position] as number;
}

/** The day's item from `pool`, or undefined when there is none. */
export function dailyItem<T>(pool: readonly T[], key: DayKey, options: DailyIndexOptions): T | undefined {
  const i = dailyIndex(key, pool.length, options);
  return i < 0 ? undefined : pool[i];
}

/**
 * Milliseconds until the next day starts in `timeZone`. On a day that a
 * clock change makes 23 or 25 hours long the answer can be off by that hour,
 * which is fine for a countdown and is why it is not used to pick puzzles.
 */
export function msUntilNextDay(now: Date | number = Date.now(), timeZone?: string): number {
  const date = typeof now === 'number' ? new Date(now) : now;
  const parts = new Intl.DateTimeFormat('en-US', {
    timeZone,
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
    hourCycle: 'h23',
  }).formatToParts(date);
  const part = Object.fromEntries(parts.map((p) => [p.type, Number(p.value)]));
  const elapsed =
    ((part.hour! * 60 + part.minute!) * 60 + part.second!) * 1000 + date.getMilliseconds();
  return DAY_MS - elapsed;
}

/**
 * @interlace/ui — games/daily
 *
 * The calendar under a daily game: which day it is for a player, which
 * puzzle that day gets, its number, and how long until the next one. Pure
 * functions, no React, no storage. Every component in `games/` builds on
 * these, and a server can call them too, so the puzzle a page renders and
 * the one a score is checked against come from the same arithmetic.
 *
 * ## Day keys
 *
 * A day is an ISO date string, `"2026-11-24"`, read in a time zone. Keys
 * sort as strings, survive JSON and storage unchanged, and compare without
 * a Date. Arithmetic on them runs in UTC, where every day has 24 hours, so
 * daylight-saving changes never skip or repeat a day.
 *
 * ## The puzzle of the day
 *
 * `dailyIndex` maps a day to an item in a pool. `order: 'sequence'` walks
 * the pool in order and starts again at the end. `order: 'shuffle'` deals
 * the pool in a seeded order that changes every cycle, and never repeats an
 * item inside a cycle. Both are deterministic: the same day, pool size and
 * seed give the same item on every device.
 */

/** An ISO calendar date, `YYYY-MM-DD`. */
